// Theme + font picker — a floating palette button that lets users switch
// themes, font size, and font family at runtime. All choices are persisted
// to localStorage and restored on page load.

import { Terminal } from "@xterm/xterm";

import { DEFAULT_THEME, DEFAULT_FONT_FAMILY, FONT_SIZES, FONT_FAMILIES, themeLabel, isFontAvailable, xtermTheme, type ThemeMap } from "../packages/terminal-core/appearance";

const STORAGE_THEME = "gotty-theme";
const STORAGE_FONT_SIZE = "gotty-font-size";
const STORAGE_FONT_FAMILY = "gotty-font-family";
const PANEL_OPEN_EVENT = "gotty-panel-open";

function applyTheme(term: Terminal | undefined, colors: Record<string, string> | undefined) {
    if (term && colors) term.options.theme = xtermTheme(colors);
}

// Re-fit the terminal after a font change. xterm measures the new cell size
// on its own render pass and the fit add-on sizes the grid from those
// metrics, so wait a frame instead of fitting against the old cell size.
// Two frames in case the option change is itself batched.
function refitSoon(refit?: () => void): void {
    if (!refit) return;
    const schedule: (cb: () => void) => void =
        typeof requestAnimationFrame === "function"
            ? (cb) => { requestAnimationFrame(cb); }
            : (cb) => { setTimeout(cb, 0); };
    schedule(() => schedule(() => refit()));
}

// Apply stored font settings; reports whether anything was applied, since a
// restored font is not what the initial fit was measured against.
function applyFontPrefs(term: Terminal | undefined): boolean {
    if (!term) return false;
    let applied = false;
    const fs = localStorage.getItem(STORAGE_FONT_SIZE);
    if (fs) {
        const n = parseInt(fs, 10);
        if (!isNaN(n) && n >= 8 && n <= 48) {
            applied = applied || term.options.fontSize !== n;
            term.options.fontSize = n;
        }
    }
    const ff = localStorage.getItem(STORAGE_FONT_FAMILY) || DEFAULT_FONT_FAMILY;
    if (ff) {
        applied = applied || term.options.fontFamily !== ff;
        term.options.fontFamily = ff;
    }
    return applied;
}

// Build the picker UI and attach it to the page
interface ThemePickerOptions {
    controls?: boolean;
    refit?: () => void;
}

export function initThemePicker(term?: Terminal, options: ThemePickerOptions = {}): void {
    const themes = (window as any).gotty_themes as ThemeMap | undefined;
    if (!themes) return;

    const names = Object.keys(themes);

    let activeThemeName = localStorage.getItem(STORAGE_THEME) || (themes[DEFAULT_THEME] ? DEFAULT_THEME : "default");
    let activeFontSize = localStorage.getItem(STORAGE_FONT_SIZE) || "";
    let activeFontFamily = localStorage.getItem(STORAGE_FONT_FAMILY) || DEFAULT_FONT_FAMILY;

    // Restore saved preferences on load, even when controls are hidden.
    if (activeThemeName && themes[activeThemeName]) {
        applyTheme(term, themes[activeThemeName]);
    }
    if (applyFontPrefs(term)) refitSoon(options.refit);

    if (options.controls === false) {
        return;
    }

    // --- Styles ---
    const style = document.createElement("style");
    style.textContent = `
#gotty-theme-btn {
    position: fixed;
    top: 42px;
    right: 10px;
    width: 28px;
    height: 28px;
    border-radius: 4px;
    border: none;
    background: rgba(0,0,0,0.7);
    color: #fff;
    padding: 0;
    cursor: pointer;
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
}
#gotty-theme-btn:hover {
    background: rgba(0,0,0,0.75);
}
#gotty-theme-btn svg {
    display: block;
}
#gotty-theme-picker {
    position: fixed;
    top: 42px;
    right: 46px;
    z-index: 9999;
    display: none;
    min-width: 190px;
    max-height: calc(100vh - 54px);
    overflow-y: auto;
}
#gotty-theme-picker.open {
    display: block;
}
#gotty-theme-picker::-webkit-scrollbar {
    width: 4px;
}
#gotty-theme-picker::-webkit-scrollbar-track {
    background: transparent;
}
#gotty-theme-picker::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,0.15);
    border-radius: 2px;
}
#gotty-theme-picker .panel {
    background: rgba(30,30,30,0.92);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 10px;
    padding: 6px;
    box-shadow: 0 8px 24px rgba(0,0,0,0.5);
}
#gotty-theme-picker .section-title {
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: rgba(255,255,255,0.35);
    padding: 10px 10px 6px;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
#gotty-theme-picker .section-title:first-child {
    padding-top: 4px;
}
#gotty-theme-picker .section-divider {
    height: 1px;
    background: rgba(255,255,255,0.08);
    margin: 4px 10px;
}
#gotty-theme-picker .theme-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 10px;
    border-radius: 6px;
    cursor: pointer;
    color: #ccc;
    font-size: 13px;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    transition: background 0.15s;
}
#gotty-theme-picker .theme-item:hover {
    background: rgba(255,255,255,0.08);
    color: #fff;
}
#gotty-theme-picker .theme-item.active {
    color: #fff;
    background: rgba(255,255,255,0.12);
}
#gotty-theme-picker .theme-swatch {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    flex-shrink: 0;
    border: 2px solid rgba(255,255,255,0.15);
}
#gotty-theme-picker .theme-name {
    flex: 1;
}

/* Font size row */
#gotty-theme-picker .font-size-row {
    display: flex;
    gap: 4px;
    padding: 2px 10px 8px;
    flex-wrap: wrap;
}
#gotty-theme-picker .size-btn {
    flex: 1;
    min-width: 28px;
    height: 26px;
    border-radius: 5px;
    border: 1px solid rgba(255,255,255,0.1);
    background: transparent;
    color: #bbb;
    font-size: 11px;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    cursor: pointer;
    transition: all 0.15s;
    padding: 0 4px;
    text-align: center;
    line-height: 26px;
}
#gotty-theme-picker .size-btn:hover {
    background: rgba(255,255,255,0.08);
    color: #fff;
}
#gotty-theme-picker .size-btn.active {
    background: rgba(255,255,255,0.15);
    color: #fff;
    border-color: rgba(255,255,255,0.3);
}

/* Font family items */
#gotty-theme-picker .font-family-item {
    padding: 7px 10px;
    border-radius: 6px;
    cursor: pointer;
    color: #ccc;
    font-size: 13px;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    transition: background 0.15s;
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0 0 1px;
}
#gotty-theme-picker .font-family-item:hover {
    background: rgba(255,255,255,0.08);
    color: #fff;
}
#gotty-theme-picker .font-family-item.active {
    color: #fff;
    background: rgba(255,255,255,0.12);
}
#gotty-theme-picker .font-family-preview {
    font-size: 14px;
    flex: 1;
}
#gotty-theme-picker .font-family-check {
    color: #4ade80;
    font-size: 12px;
    visibility: hidden;
}
#gotty-theme-picker .font-family-item.active .font-family-check {
    visibility: visible;
}
#gotty-theme-picker .font-family-item.unavailable {
    opacity: 0.4;
    cursor: default;
}
#gotty-theme-picker .font-family-item.unavailable:hover {
    background: transparent;
    color: #ccc;
}
#gotty-theme-picker .font-family-tag {
    font-size: 10px;
    color: rgba(255,255,255,0.35);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
`;

    document.head.appendChild(style);

    // --- Button ---
    const btn = document.createElement("button");
    btn.id = "gotty-theme-btn";
    btn.type = "button";
    btn.innerHTML = '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M4.5 3.5h7M8 3.5v9M5.5 12.5h5M3 6h10" stroke="rgba(255,255,255,0.7)" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    btn.title = "Display settings";
    btn.setAttribute("aria-label", "Display settings");
    document.body.appendChild(btn);

    // --- Dropdown ---
    const container = document.createElement("div");
    container.id = "gotty-theme-picker";

    const panel = document.createElement("div");
    panel.className = "panel";

    // ── Themes section ──
    const themeTitle = document.createElement("div");
    themeTitle.className = "section-title";
    themeTitle.textContent = "Themes";
    panel.appendChild(themeTitle);

    for (const name of names) {
        const colors = themes[name];
        const item = document.createElement("div");
        item.className = "theme-item";
        if (name === activeThemeName) {
            item.classList.add("active");
        }

        const swatch = document.createElement("div");
        swatch.className = "theme-swatch";
        swatch.style.background = colors?.background || "#333";
        item.appendChild(swatch);

        const label = document.createElement("span");
        label.className = "theme-name";
        label.textContent = themeLabel(name);
        item.appendChild(label);

        if (name === activeThemeName) {
            const check = document.createElement("span");
            check.textContent = "✓";
            check.style.color = "#4ade80";
            item.appendChild(check);
        }

        item.addEventListener("click", () => {
            applyTheme(term, colors);
            localStorage.setItem(STORAGE_THEME, name);
            // Update active state
            container.querySelectorAll(".theme-item").forEach((el) => {
                el.classList.remove("active");
                const last = el.lastChild;
                if (last && last.textContent === "✓") {
                    el.removeChild(last);
                }
            });
            item.classList.add("active");
            const check = document.createElement("span");
            check.textContent = "✓";
            check.style.color = "#4ade80";
            item.appendChild(check);
            // Don't close — let user tweak fonts too
        });

        panel.appendChild(item);
    }

    // ── Divider ──
    const divider = document.createElement("div");
    divider.className = "section-divider";
    panel.appendChild(divider);

    // ── Font Size section ──
    const sizeTitle = document.createElement("div");
    sizeTitle.className = "section-title";
    sizeTitle.textContent = "Font Size";
    panel.appendChild(sizeTitle);

    const sizeRow = document.createElement("div");
    sizeRow.className = "font-size-row";

    const savedSize = activeFontSize ? parseInt(activeFontSize, 10) : null;
    const currentSize = (savedSize && !isNaN(savedSize)) ? savedSize : (term?.options?.fontSize || 14);

    for (const sz of FONT_SIZES) {
        const sb = document.createElement("button");
        sb.className = "size-btn";
        sb.textContent = String(sz);
        if (sz === currentSize) {
            sb.classList.add("active");
        }
        sb.addEventListener("click", () => {
            if (term) {
                term.options.fontSize = sz;
            }
            localStorage.setItem(STORAGE_FONT_SIZE, String(sz));
            refitSoon(options.refit);
            sizeRow.querySelectorAll(".size-btn").forEach((el) => el.classList.remove("active"));
            sb.classList.add("active");
        });
        sizeRow.appendChild(sb);
    }

    panel.appendChild(sizeRow);

    // ── Font Family section ──
    const ffTitle = document.createElement("div");
    ffTitle.className = "section-title";
    ffTitle.textContent = "Font Family";
    panel.appendChild(ffTitle);

    const currentFF = activeFontFamily || term?.options?.fontFamily || "";

    for (const ff of FONT_FAMILIES) {
        // The picker cannot load fonts, so it can only use what is already
        // installed. A name that is missing silently falls back to monospace
        // and looks like the click did nothing, so mark those as unavailable
        // and leave them unselectable.
        const available = isFontAvailable(ff.name);
        const item = document.createElement("div");
        item.className = "font-family-item";
        if (ff.value === currentFF) {
            item.classList.add("active");
        }
        if (!available) {
            item.classList.add("unavailable");
        }

        const preview = document.createElement("span");
        preview.className = "font-family-preview";
        preview.textContent = ff.name;
        preview.style.fontFamily = ff.value;
        item.appendChild(preview);

        if (!available) {
            const tag = document.createElement("span");
            tag.className = "font-family-tag";
            tag.textContent = "not installed";
            item.appendChild(tag);
        }

        const check = document.createElement("span");
        check.className = "font-family-check";
        check.textContent = "✓";
        item.appendChild(check);

        if (available) {
            item.addEventListener("click", () => {
                if (term) {
                    term.options.fontFamily = ff.value;
                }
                localStorage.setItem(STORAGE_FONT_FAMILY, ff.value);
                panel.querySelectorAll(".font-family-item").forEach((el) => {
                    el.classList.remove("active");
                });
                item.classList.add("active");
                refitSoon(options.refit);
            });
        }

        panel.appendChild(item);
    }

    container.appendChild(panel);
    document.body.appendChild(container);

    // --- Toggle ---
    btn.addEventListener("click", (e) => {
        e.stopPropagation();
        if (container.classList.contains("open")) {
            container.classList.remove("open");
            return;
        }
        window.dispatchEvent(new CustomEvent(PANEL_OPEN_EVENT, { detail: "display" }));
        container.classList.add("open");
    });

    // Close on outside click
    document.addEventListener("click", (e) => {
        if (!container.contains(e.target as Node) && e.target !== btn) {
            container.classList.remove("open");
        }
    });

    window.addEventListener(PANEL_OPEN_EVENT, (event) => {
        if ((event as CustomEvent<string>).detail !== "display") {
            container.classList.remove("open");
        }
    });
}
